 @Test void quoteSnapshotHasNoInventoryOrCouponReservations(){String u=consumer(),o=ready(),i=addFor(u,o),a=addressFor(u);shipping();String c=coupon(u,"PLATFORM",200,0);long before=balance(o);var q=quoteFor(u,i,a,List.of(c),false,key());assertEquals(200,q.status(),q.body().toString());assertEquals(before,balance(o));assertEquals(1,db.queryForObject("SELECT count(*) FROM pricing_quote_discount_allocations WHERE quote_id=?",Integer.class,UUID.fromString(q.data().get("quote_id").asString())));db.update("UPDATE user_coupons SET status='VOID',version=version+1 WHERE id=?",UUID.fromString(c));assertEquals("INVALIDATED",read("/consumer/checkout/quotes/"+q.data().get("quote_id").asString(),u).data().get("status").asString());}

 @Test void expirationWorkerPersistsExpiredAndKeepsSnapshot(){String u=consumer(),o=ready(),i=addFor(u,o),a=addressFor(u);shipping();var q=quoteFor(u,i,a,List.of(),false,key());assertEquals(200,q.status());String id=q.data().get("quote_id").asString();db.update("UPDATE auth_session SET expires_at=refresh_expires_at WHERE access_token_hash=?",crypto.hash(u));OFFSET.set(1000);new cn.pawday.checkout.QuoteExpiryWorker(db,clock,true).expire();var current=read("/consumer/checkout/quotes/"+id,u);assertEquals(200,current.status(),current.body().toString());assertEquals("EXPIRED",current.data().get("status").asString());assertEquals(2500,current.data().get("payable_amount_fen").asInt());assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("UPDATE pricing_quotes SET status='ACTIVE',version=version+1 WHERE id=?",UUID.fromString(id)));}
 @Test void concurrentCartCommandsAndSameQuoteReplayProduceOneResult()throws Exception{String u=consumer(),o=ready();String k=key();var pool=Executors.newFixedThreadPool(2);try{var start=new CountDownLatch(1);var futures=new ArrayList<Future<Response>>();for(int x=0;x<2;x++)futures.add(pool.submit(()->{start.await();return req("POST","/consumer/cart/items",Map.of("offer_id",o,"quantity",2),u,Map.of("Idempotency-Key",k));}));start.countDown();var r1=futures.get(0).get(20,TimeUnit.SECONDS);var r2=futures.get(1).get(20,TimeUnit.SECONDS);assertEquals(200,r1.status());assertEquals(r1.data(),r2.data());assertEquals(2,read("/consumer/cart",u).data().get("items").get(0).get("quantity").asInt());String a=addressFor(u);shipping();String qkey=key();var f1=pool.submit(()->quoteFor(u,r1.id(),a,List.of(),false,qkey));var f2=pool.submit(()->quoteFor(u,r1.id(),a,List.of(),false,qkey));var q1=f1.get(20,TimeUnit.SECONDS);var q2=f2.get(20,TimeUnit.SECONDS);assertEquals(200,q1.status(),q1.body().toString());assertEquals(q1.data(),q2.data());assertEquals(1,db.queryForObject("SELECT count(*) FROM pricing_quotes WHERE user_id=?",Integer.class,user(u)));}finally{pool.shutdownNow();}}
 @Test void twoMerchantsGetOneShippingGroupEachAndStableAllocations(){String u=consumer(),o=ready(),i=addFor(u,o),a=addressFor(u);shipping();UUID m=UUID.randomUUID(),other=UUID.randomUUID();db.update("INSERT INTO merchant(id,name,status) VALUES (?,'TEST second merchant','ACTIVE')",m);db.update("INSERT INTO offers(id,merchant_id,sku_id,sale_price_fen,fulfillment_sla,sale_status) VALUES (?,?,?,1000,'TEST-only','ACTIVE')",other,m,UUID.fromString(sku));db.update("INSERT INTO inventory_balances(offer_id,on_hand_qty) VALUES (?,20)",other);db.update("INSERT INTO shipping_rule_versions(id,merchant_id,version_no,province_codes,base_fen,per_kg_fen,created_by) VALUES (?,?,1,'[\"310000\"]',400,0,?)",UUID.randomUUID(),m,adminPrincipal);String j=addFor(u,other.toString()),c=coupon(u,"PLATFORM",333,0);var body=Map.of("cart_item_ids",List.of(j,i),"address_id",a,"coupon_ids",List.of(c));var q=req("POST","/consumer/checkout/quotes",body,u,Map.of("Idempotency-Key",key()));assertEquals(200,q.status(),q.body().toString());assertEquals(2,q.data().get("merchant_groups").size());assertEquals(4567,q.data().get("payable_amount_fen").asInt());var q2=req("POST","/consumer/checkout/quotes",Map.of("cart_item_ids",List.of(i,j),"address_id",a,"coupon_ids",List.of(c)),u,Map.of("Idempotency-Key",key()));assertEquals(200,q2.status());assertEquals(q.data().get("items"),q2.data().get("items"));assertEquals(333,q.data().get("items").get(0).get("discount_amount_fen").asInt()+q.data().get("items").get(1).get("discount_amount_fen").asInt());}
 @Test void newShippingVersionAndInsufficientStockInvalidateOldQuotes(){String u=consumer(),o=ready(),i=addFor(u,o),a=addressFor(u);shipping();var q=quoteFor(u,i,a,List.of(),false,key());assertEquals(200,q.status());db.update("INSERT INTO shipping_rule_versions(id,merchant_id,version_no,province_codes,base_fen,per_kg_fen,created_by) VALUES (?,?,2,'[\"310000\"]',600,0,?)",UUID.randomUUID(),merchantId,adminPrincipal);assertEquals("INVALIDATED",read("/consumer/checkout/quotes/"+q.data().get("quote_id").asString(),u).data().get("status").asString());var fresh=quoteFor(u,i,a,List.of(),false,key());assertEquals(200,fresh.status());assertEquals(2600,fresh.data().get("payable_amount_fen").asInt());assertEquals(201,adjust(o,-19,1,key(),merchant).status());assertEquals("INVALIDATED",read("/consumer/checkout/quotes/"+fresh.data().get("quote_id").asString(),u).data().get("status").asString());}
 @Test void stoppedCouponDefinitionAndDeletedPetInvalidateFrozenQuote(){String u=consumer(),o=ready(),a=addressFor(u);UUID pet=pet(u,"CAT");var added=req("POST","/consumer/cart/items",Map.of("offer_id",o,"quantity",1,"pet_id",pet.toString()),u,Map.of("Idempotency-Key",key()));assertEquals(200,added.status());shipping();String c=coupon(u,"PLATFORM",10,0);var q=quoteFor(u,added.id(),a,List.of(c),false,key());assertEquals(200,q.status());db.update("UPDATE coupon_definitions SET status='STOPPED' WHERE id=(SELECT definition_id FROM user_coupons WHERE id=?)",UUID.fromString(c));assertEquals("INVALIDATED",read("/consumer/checkout/quotes/"+q.data().get("quote_id").asString(),u).data().get("status").asString());var fresh=quoteFor(u,added.id(),a,List.of(),false,key());assertEquals(200,fresh.status());db.update("UPDATE pets SET status='DELETED',version=version+1 WHERE id=?",pet);assertEquals("INVALIDATED",read("/consumer/checkout/quotes/"+fresh.data().get("quote_id").asString(),u).data().get("status").asString());}
 @Test void membershipAndCouponsNeverBelongToClientClaim(){String u=consumer(),other=consumer(),o=ready(),i=addFor(u,o),a=addressFor(u);shipping();String c=coupon(other,"PLATFORM",100,0);assertEquals(422,quoteFor(u,i,a,List.of(c),false,key()).status());assertEquals(0,read("/consumer/checkout/benefits",u).data().get("coupons").size());assertEquals(400,req("POST","/consumer/checkout/quotes",Map.of("cart_item_ids",List.of(i,i),"address_id",a),u,Map.of("Idempotency-Key",key())).status());assertEquals(400,req("POST","/consumer/checkout/quotes",Map.of("cart_item_ids",List.of(i),"address_id",a,"payable_amount_fen",1),u,Map.of("Idempotency-Key",key())).status());}
